import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { parseOptions, selected, discoverRoutes, escapeHtml, imageName, serve } from './core.mjs';
import { writeReport } from './report.mjs';
import { comparePng } from './capture.mjs';
import { PNG } from 'pngjs';
const temporary = async t => { const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'visual-test-')); t.after(() => fs.rm(dir, { recursive: true, force: true })); return dir; };
test('defaults compare merge-base across desktop and mobile', () => { const o = parseOptions([]); assert.equal(o.comparison, 'merge-base'); assert.deepEqual(o.profiles, ['desktop', 'mobile']); assert.deepEqual(o.routes, []); });
test('explicit profiles/routes are deduplicated and parsed', () => { const o = parseOptions(['--profiles', 'mobile,mobile', '--routes', '/guides/, /devices', '--comparison', 'base-tip']); assert.deepEqual(o.profiles, ['mobile']); assert.deepEqual(o.routes, ['/guides/', '/devices']); assert.equal(o.comparison, 'base-tip'); });
for (const args of [['--wat'], ['--base'], ['--profiles', 'evil'], ['--profiles', ''], ['--color', 'pink'], ['--routes', '../secret'], ['--routes', '/a/../b'], ['--routes', '/a?b'], ['--routes', '/a\\b'], ['--comparison', 'all'], ['--base-dir', 'x'], ['--skip-build'], ['--head-sha', 'bad']]) test(`reject unsafe/invalid input ${JSON.stringify(args)}`, () => assert.throws(() => parseOptions(args)));
test('route selection distinguishes prefixes and exact paths', () => { assert.ok(selected('/guides/a', ['/guides/'])); assert.ok(selected('/devices', ['/devices'])); assert.ok(!selected('/devices/x', ['/devices'])); assert.ok(selected('/anything', [])); });
test('route discovery uses rendered output including generated routes and index paths', async t => { const dir = await temporary(t); await fs.mkdir(path.join(dir, 'apis')); for (const file of ['index.html', '404.html', 'devices.html', 'apis/index.html', 'apis/generated-id.html']) await fs.writeFile(path.join(dir, file), 'test'); assert.deepEqual([...await discoverRoutes(dir)].sort(), [['/', 'index.html'], ['/apis/', 'apis/index.html'], ['/apis/generated-id', 'apis/generated-id.html'], ['/devices', 'devices.html']]); });
test('route discovery rejects empty output and filesystem links', async t => { const dir = await temporary(t); await assert.rejects(discoverRoutes(dir), /No rendered/); await fs.symlink('/etc/passwd', path.join(dir, 'bad.html')); await assert.rejects(discoverRoutes(dir), /Symlink/); });
test('HTML escapes untrusted route/error content and filenames are hashes', () => { assert.equal(escapeHtml('<script>"&\''), '&lt;script&gt;&quot;&amp;&#39;'); assert.match(imageName('/../unsafe#<x>', 'desktop'), /^[a-f0-9]{20}-desktop-page$/); });
test('report emits paired images, metrics, added/removed, and escapes errors', async t => { const dir = await temporary(t); const report = { baseSha: 'a'.repeat(40), headSha: 'b'.repeat(40), generatedAt: 'now', errors: ['<script>alert(1)</script>'], pages: [{ route: '/x<img>', profile: 'desktop', state: 'page', status: 'changed', base: 'images/a.png', head: 'images/b.png', diff: 'images/d.png', diffPixels: 2, diffRatio: .25 }, { route: '/new', status: 'added' }] }; await writeReport(dir, report); const html = await fs.readFile(path.join(dir, 'index.html'), 'utf8'); assert.ok(html.includes('&lt;script&gt;')); assert.ok(!html.includes('<script>')); assert.ok(html.includes('25.000%')); assert.equal(JSON.parse(await fs.readFile(path.join(dir, 'summary.json'))).counts.added, 1); });
function png(width, height, value = 255) { const image = new PNG({ width, height }); image.data.fill(value); return PNG.sync.write(image); }
test('equal images do not differ', () => { const r = comparePng(png(3, 3), png(3, 3)); assert.equal(r.diffPixels, 0); assert.equal(r.sizeChanged, false); });
test('different dimensions are retained even with no colored pixels changed', () => { const r = comparePng(png(3, 3), png(3, 4)); assert.equal(r.diffPixels, 0); assert.equal(r.sizeChanged, true); assert.deepEqual(r.headSize, [3, 4]); });
test('pixel differences are counted', () => { const r = comparePng(png(3, 3), png(3, 3, 0)); assert.ok(r.diffPixels > 0); });
test('static server supports nested base, clean URLs and disallows outside files', async t => { const dir = await temporary(t); await fs.writeFile(path.join(dir, 'index.html'), 'home'); await fs.writeFile(path.join(dir, 'page.html'), 'page'); await fs.symlink('/etc/passwd', path.join(dir, 'secret')); const server = await serve(dir); t.after(server.close); assert.equal(await (await fetch(server.url)).text(), 'home'); assert.equal(await (await fetch(server.url + 'page')).text(), 'page'); assert.equal((await fetch(new URL('/page', server.url))).status, 404); assert.equal((await fetch(server.url + 'secret')).status, 404); assert.equal((await fetch(server.url + '%2e%2e/secret')).status, 404); });

test('static server preserves distinct /foo and /foo/ rendered routes', async t => { const dir = await temporary(t); await fs.mkdir(path.join(dir, 'foo')); await fs.writeFile(path.join(dir, 'foo.html'), 'plain page'); await fs.writeFile(path.join(dir, 'foo/index.html'), 'directory page'); const server = await serve(dir); t.after(server.close); assert.equal(await (await fetch(server.url + 'foo')).text(), 'plain page'); assert.equal(await (await fetch(server.url + 'foo/')).text(), 'directory page'); });
